/**
 * Look up a guest by username (case-insensitive).
 * @param {string} username
 * @returns {GuestProfile|undefined}
 */
export function getGuestByUsername(username) {
  if (!username) return undefined;
  const u = String(username).trim().toLowerCase();
  return GUESTS.find((g) => g.username && g.username.toLowerCase() === u);
}

/**
 * Look up a guest by their Firebase auth email (case-insensitive).
 * This is the canonical link between an auth account and a guest.
 * @param {string} email
 * @returns {GuestProfile|undefined}
 */
export function getGuestByEmail(email) {
  if (!email) return undefined;
  const e = String(email).trim().toLowerCase();
  return GUESTS.find((g) => g.firebaseEmail && g.firebaseEmail.toLowerCase() === e);
}

/**
 * Look up a guest by id.
 * @param {string} id
 * @returns {GuestProfile|undefined}
 */
export function getGuest(id) {
  return GUESTS.find((g) => g.id === id);
}

/**
 * All guests that are not marked deleted.
 * @returns {GuestProfile[]}
 */
export function getActiveGuests() {
  return GUESTS.filter((g) => !g._deleted);
}

/**
 * Guests assigned to a given cabin unit.
 * @param {string} unit
 * @returns {GuestProfile[]}
 */
export function getGuestsByUnit(unit) {
  return GUESTS.filter((g) => g.hasCabin && g.unit === unit);
}

/**
 * Load deleted guest ids from Firestore and mark them on the registry.
 * @returns {Promise<string[]>}
 */
export async function loadDeletedGuestIds() {
  try {
    const snap = await getDocs(collection(db, "guests"));
    const deleted = [];
    snap.forEach((doc) => {
      const data = doc.data();
      if (data && data._deleted) deleted.push(doc.id);
    });
    deleted.forEach((id) => {
      const g = GUESTS.find((x) => x.id === id);
      if (g) g._deleted = true;
    });
    return deleted;
  } catch (error) {
    console.warn("loadDeletedGuestIds failed", error);
    return [];
  }
}

export default GUESTS;